namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MaximumRatePoints = 10;

    public int Apply(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        var ratePoints = Math.Min(BaseRatePoints(loyaltyTier) + BandBonusPoints(subtotalCents), MaximumRatePoints);
        var discountCents = (int)((long)subtotalCents * ratePoints / 100);
        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier)),
    };

    private static int BandBonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20_000 => 3,
        >= 5_000 => 1,
        _ => 0,
    };
}
E
